  side:THREE.BackSide, depthWrite:false,
  uniforms:{cH:{value:C(0xffa384)},cP:{value:C(0xd8709c)},cM:{value:C(0x6d4c94)},cI:{value:C(0x211f55)},cT:{value:C(0x0a0b26)}},
  vertexShader:`varying vec3 vP; void main(){vP=position; gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.);}`,
  fragmentShader:`varying vec3 vP; uniform vec3 cH,cP,cM,cI,cT;
   void main(){ vec3 d=normalize(vP); float h=max(d.y,0.);
    vec3 c=mix(cH,cP,smoothstep(0.,.09,h)); c=mix(c,cM,smoothstep(.07,.28,h)); c=mix(c,cI,smoothstep(.25,.6,h)); c=mix(c,cT,smoothstep(.55,1.,h));
    float g=pow(max(0.,-d.z),4.)*exp(-h*7.); c+=vec3(.55,.22,.1)*g*.6;
    if(d.y<0.) c=mix(cH*.8,vec3(.35,.25,.45),clamp(-d.y*6.,0.,1.));
    gl_FragColor=vec4(c,1.);
    #include <colorspace_fragment>
   }`}));
sky.renderOrder=-2; scene.add(sky);

